<?php require 'config.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$sub=trim($_POST['subject']??'');$desc=trim($_POST['description']??'');$cat=$_POST['category']??'Incident';$pri=$_POST['priority']??'P3';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||!$sub||!$desc){flash('error','Complete all required fields.');}else{$s=db()->prepare('INSERT INTO support_tickets(user_id,name,email,category,priority,subject,description) VALUES(?,?,?,?,?,?,?)');$s->execute([current_user()['id']??null,$name,$email,$cat,$pri,$sub,$desc]);$id=db()->lastInsertId();flash('success','Support ticket MB-'.str_pad($id,4,'0',STR_PAD_LEFT).' created.');header('Location: support.php');exit;}}$title='Support | MediBook';require 'partials/header.php';$u=current_user();?><section class="page-title"><span class="eyebrow">L1 service desk</span><h1>How can we help?</h1><p>Log a demonstration incident or service request with evidence-friendly details.</p></section><section class="section two"><form method="post" class="panel wide"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="form-grid"><label>Name<input name="name" value="<?=e($u['name']??'')?>" required></label><label>Email<input type="email" name="email" value="<?=e($u['email']??'')?>" required></label><label>Category<select name="category"><option>Incident</option><option>Service Request</option><option>Access Request</option><option>Security Incident</option></select></label><label>Priority<select name="priority"><option>P1 - Critical</option><option>P2 - High</option><option selected>P3 - Medium</option><option>P4 - Low</option></select></label></div><label>Subject<input name="subject" required></label><label>Description<textarea name="description" rows="5" placeholder="What happened? Who is affected? When did it start? What changed? Include errors and timestamps, but no passwords or medical details." required></textarea></label><button class="btn">Create demo ticket</button></form><aside class="checklist"><h2>For faster support</h2><p>Include the time and timezone.</p><p>Explain who and what is affected.</p><p>Copy the exact error message.</p><p>Tell us what changed recently.</p><p>Never include passwords, OTPs or patient reports.</p></aside></section><?php require 'partials/footer.php';?>